class Solution {
public:
    vector<int> answerQueries(vector<int>& nums, vector<int>& queries) {
        sort(nums.begin(), nums.end());
        int n = nums.size();
        vector<long long> prefix(n);
        long long s = 0;
        for (int i = 0; i < n; i++) {
            s += nums[i];
            prefix[i] = s;
        }
        vector<int> ans;
        ans.reserve(queries.size());
        for (int q : queries) {
            int idx = upper_bound(prefix.begin(), prefix.end(), (long long)q) - prefix.begin();
            ans.push_back(idx);
        }
        return ans;
    }
};
